Demo.Run<object[]>(async demo =>
{
    var first = await demo.SaveOneAsync("shop.currency", "EUR");
    await demo.SaveOneAsync("shop.currency", "USD", first.Version);

    var stale = await demo.Source.SaveAsync(Demo.App, Scope.App, [Demo.Write("shop.currency", "GBP", first.Version)]);
    var rows = await demo.Source.LoadAsync(Demo.App, Scope.App);

    return [stale.Status, stale.Code!, $"stored: {rows.Single().Value}"];
});

Demo.Run<object[]>(async demo =>
{
