Demo.Run<object[]>(async demo =>
{
    var row = await demo.SaveOneAsync("shop.currency", "EUR");

    var result = await demo.Source.SaveAsync(Demo.App, Scope.App,
        [new SettingWrite { Key = "shop.currency", Reset = true, Version = row.Version }]);
