Demo.Run(async demo =>
{
    await demo.SaveOneAsync("shop.currency", "EUR");
    await demo.SaveOneAsync("shop.currency", "USD", scope: Demo.Tenant);

    var rows = await demo.UseDbAsync(db => db.Entity<SettingValueEntry>().OrderBy(e => e.ScopeKind).ToListAsync());

    return rows.Select(e => $"{e.AppCode} scope {e.ScopeKind}:{e.ScopeId} {e.Key} = {e.Value}").ToArray();
});

Demo.Run<object[]>(async demo =>
{
    var first = await demo.SaveOneAsync("shop.currency", "EUR");
    demo.Clock.Advance(TimeSpan.FromHours(2));
    await demo.SaveOneAsync("shop.currency", "USD", first.Version);

    var entry = await demo.UseDbAsync(db => db.Entity<SettingValueEntry>().SingleAsync());

    return [$"created {entry.CreateDate:HH:mm}", $"modified {entry.ModifiedDate:HH:mm}"];
});

Demo.Run(async demo =>
{
    await demo.Source.SyncKeysAsync(Demo.App,
    [
        new SettingKeyRow { Key = "shop.currency", Kind = "choice", Access = SettingAccess.Public },
        new SettingKeyRow { Key = "shop.api-token", Kind = "text", Access = SettingAccess.Secret }
    ]);

    var keys = await demo.UseDbAsync(db => db.Entity<SettingKeyEntry>().OrderBy(e => e.Key).ToListAsync());

    return keys.Select(e => $"{e.Key} ({e.Kind}, {e.Access}, active {e.IsActive})").ToArray();
});

Demo.Run(async demo =>
{
    await demo.Source.SyncKeysAsync(Demo.App, [Key("shop.title", "text"), Key("shop.page-size", "integer")]);
    demo.Clock.Advance(TimeSpan.FromDays(1));
    await demo.Source.SyncKeysAsync(Demo.App, [Key("shop.title", "text"), Key("shop.logo", "url")]);

    var keys = await demo.UseDbAsync(db => db.Entity<SettingKeyEntry>().OrderBy(e => e.Key).ToListAsync());

    return keys.Select(e => $"{e.Key}: active {e.IsActive}, first seen {e.FirstSeenDate:MM-dd}, synced {e.SyncDate:MM-dd}").ToArray();
});

Demo.Run<string[]>(async demo =>
{
    await demo.Source.SyncKeysAsync(Demo.App, [Key("shop.logo", "url")]);
    await demo.Source.SyncKeysAsync(Demo.App, []);
    var gone = await demo.UseDbAsync(db => db.Entity<SettingKeyEntry>().SingleAsync());

    await demo.Source.SyncKeysAsync(Demo.App, [Key("shop.logo", "url")]);
    var back = await demo.UseDbAsync(db => db.Entity<SettingKeyEntry>().SingleAsync());

    return [$"after removal: active {gone.IsActive}", $"after it returns: active {back.IsActive}"];
});

